/* eslint-disable @typescript-eslint/no-unused-vars -- shared helpers, pasted in front of the Code nodes that use them */
/**
 * Shared helpers, pasted by pack-workflows.mjs in front of every Code node that needs them:
 * addresses, query strings, escaping, slugs, Strapi admin links, and the one page layout
 * with navigation used by all review pages. Nothing here talks to an API.
 */

const CMS = "https://cms.beer.de";
// Links to the website go to staging until the new site is live on beer.de.
const SITE = "https://staging.beer.de";

const qs = (query) =>
  Object.entries(query)
    .filter(([, value]) => value !== undefined && value !== null)
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
    .join("&");

const esc = (value) =>
  String(value ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);

const slugify = (value, max = 60) =>
  String(value ?? "")
    .toLowerCase()
    .replace(/ä/g, "ae").replace(/ö/g, "oe").replace(/ü/g, "ue").replace(/ß/g, "ss")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, max)
    .replace(/-$/, "");

const UID = {
  projects: "api::project.project",
  articles: "api::article.article",
  "site-pages": "api::site-page.site-page",
  "kitchen-topics": "api::kitchen-topic.kitchen-topic",
  regions: "api::region.region",
  materials: "api::material.material",
  appliances: "api::appliance.appliance",
  brands: "api::brand.brand",
  "furniture-items": "api::furniture-item.furniture-item",
};
const adminUrl = (api, documentId, locale = "de") =>
  `${CMS}/admin/content-manager/collection-types/${UID[api] ?? api}/${documentId}?plugins[i18n][locale]=${locale}`;

const when = (iso) => (iso ? new Date(iso).toLocaleString("de-DE", { timeZone: "Europe/Berlin", dateStyle: "medium", timeStyle: "short" }) : "");

// Same words as the website uses for a "useful" photo description.
const weakAlt = (alt) => {
  const text = String(alt ?? "").trim();
  return text.length < 30 || !text.includes(" ") || /\.(jpe?g|png|webp|gif)$/i.test(text);
};

const NAV = [
  ["Übersicht", "/webhook/redaktion"],
  ["SEO-Prüfung", "/webhook/seo-pruefung"],
  ["SEO-Vorschläge", "/webhook/seo-vorschlaege"],
  ["Projekttexte", "/webhook/beer-texte"],
  ["Ratgeber", "/webhook/beer-ratgeber"],
  ["GEO-Monitor", "/webhook/geo-monitor"],
  ["Regionen", "/webhook/beer-regionen"],
  ["Newsletter", "/webhook/beer-newsletter"],
  ["Meldungen", "/webhook/0b1c2d3e-4f5a-4b6c-8d7e-9f0a1b2c3d06/chat"],
  ["Neue Seite", "/webhook/7d8e9f0a-1b2c-4d3e-8f4a-5b6c7d8e9f07/chat"],
];

/** One full HTML page in the shared layout. `active` is the NAV label to highlight. */
function page(title, active, body, notice = "") {
  return `<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(title)} · BEER Redaktion</title><style>
:root{--ink:#1d1d1b;--muted:#6b6760;--line:#e3ded6;--paper:#faf8f5;--card:#fff;--red:#a4161a;--amber:#7a5c00;--green:#2d6a4f}
*{box-sizing:border-box}body{font:15px/1.55 system-ui,-apple-system,"Segoe UI",sans-serif;margin:0;color:var(--ink);background:var(--paper)}
nav{display:flex;flex-wrap:wrap;gap:4px 14px;padding:12px 16px;border-bottom:1px solid var(--line);background:var(--card);font-size:14px}
nav a{color:var(--muted);text-decoration:none}nav a.on{color:var(--ink);font-weight:600}nav b{margin-right:8px}
main{max-width:1080px;margin:0 auto;padding:24px 16px 64px}h1{font-weight:500;font-size:28px;margin:0 0 4px}
h2{font-size:19px;margin:28px 0 8px}h3{font-size:15px;margin:16px 0 6px}a{color:var(--ink)}
.small{font-size:13px;color:var(--muted)}.card{background:var(--card);border:1px solid var(--line);border-radius:6px;padding:16px 18px;margin:14px 0}
table{border-collapse:collapse;width:100%}td,th{vertical-align:top;text-align:left;padding:7px 8px;border-bottom:1px solid #ece8e1}th{font-weight:600;font-size:13px;color:var(--muted)}
ul{margin:0;padding-left:18px}.fehler{color:var(--red)}.hinweis{color:var(--amber)}.ok{color:var(--green)}
.kpi{display:flex;gap:28px;margin:16px 0 20px;flex-wrap:wrap}.kpi b{display:block;font-size:24px;font-weight:600}
.notice{background:#eef6f0;border:1px solid #b7d8c2;padding:8px 12px;border-radius:4px;margin:12px 0}
.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}form{margin:0;display:inline-flex;flex-wrap:wrap;gap:8px;align-items:center}
button{font:inherit;padding:7px 14px;border:1px solid var(--ink);background:#fff;border-radius:4px;cursor:pointer}button.primary{background:var(--ink);color:#fff}
input,select,textarea{font:inherit;padding:6px 8px;border:1px solid #cfc9bf;border-radius:4px;background:#fff}textarea{width:100%;min-height:90px}
dl{display:grid;grid-template-columns:160px 1fr;gap:4px 12px;margin:0}dt{color:var(--muted)}dd{margin:0}.pre{white-space:pre-wrap}
details>summary{cursor:pointer;padding:10px 0}img{border-radius:3px;display:block;max-width:100%}
@media (max-width:640px){dl{grid-template-columns:1fr}.kpi{gap:18px}}</style></head><body>
<nav><b>BEER Redaktion</b>${NAV.map(([label, href]) => `<a href="${href}"${label === active ? ' class="on"' : ""}>${esc(label)}</a>`).join("")}</nav>
<main><h1>${esc(title)}</h1>${notice ? `<p class="notice">${notice}</p>` : ""}${body}</main></body></html>`;
}

/** A small POST form with hidden fields and one button. */
function button(action, fields, label, primary = false) {
  const hidden = Object.entries(fields).map(([k, v]) => `<input type="hidden" name="${esc(k)}" value="${esc(v)}">`).join("");
  return `<form method="post" action="${esc(action)}">${hidden}<button${primary ? ' class="primary"' : ""}>${esc(label)}</button></form>`;
}

/* eslint-disable @typescript-eslint/no-unused-vars -- shared helpers, pasted in front of the Code nodes that use them */
/**
 * Shared by the n8n Code nodes that talk to Claude (pasted in by pack-workflows.mjs).
 * claudeRequest() builds a Messages API body; the HTTP node "… Claude" sends it with the
 * credential "Claude API (BEER)". claudeAnswer() reads the JSON answer back.
 */

const MODEL = "claude-opus-5-5";

/**
 * schema: JSON schema for structured output (strict JSON back).
 * webSearch: number of searches allowed; then the answer is asked for as a JSON block in the
 * text instead, since search results come back with citations.
 */
function claudeRequest({ system, user, schema, effort = "medium", maxTokens = 16000, webSearch = 0 }) {
  const request = {
    model: MODEL,
    max_tokens: maxTokens,
    system,
    output_config: { effort },
    // Lets the API answer with a fallback model when a request is declined.
    fallbacks: "default",
    messages: [{ role: "user", content: user }],
  };
  if (webSearch) {
    request.tools = [
      {
        type: "web_search_20260209",
        name: "web_search",
        max_uses: webSearch,
        user_location: { type: "approximate", city: "Freising", region: "Bayern", country: "DE", timezone: "Europe/Berlin" },
      },
    ];
    if (schema) {
      request.system += `\n\nAntworte am Ende ausschließlich mit einem JSON-Objekt nach diesem Schema, ohne weiteren Text:\n${JSON.stringify(schema)}`;
    }
  } else if (schema) {
    request.output_config.format = { type: "json_schema", schema };
  }
  return request;
}

/** { value } with the parsed JSON answer, or { error } when the call produced none. */
function claudeAnswer(response) {
  if (!response || response.type === "error" || response.error) {
    // After retries the HTTP node passes the failure on as { error: "…" } or { error: { message } }.
    const error = response?.error;
    const message = typeof error === "string" ? error : error?.message ?? response?.message ?? "keine Antwort";
    return { error: `Claude: ${message}` };
  }
  if (response.stop_reason === "refusal") return { error: "Claude hat abgelehnt." };
  if (response.stop_reason === "max_tokens") return { error: "Antwort abgeschnitten (max_tokens)." };
  if (response.stop_reason === "pause_turn") return { error: "Suche nicht fertig geworden – bitte erneut starten." };
  const text = (response.content ?? []).filter((block) => block.type === "text").map((block) => block.text).join("");
  for (const candidate of [text, text.match(/```(?:json)?\s*([\s\S]*?)```/)?.[1], text.slice(text.indexOf("{"), text.lastIndexOf("}") + 1)]) {
    if (!candidate) continue;
    try {
      return { value: JSON.parse(candidate), sources: webSources(response) };
    } catch {
      // try the next form
    }
  }
  return { error: "Antwort war kein gültiges JSON." };
}

/** The pages Claude's web searches returned (title and address), for reports. */
function webSources(response) {
  const seen = new Map();
  for (const block of response.content ?? []) {
    if (block.type !== "web_search_tool_result" || !Array.isArray(block.content)) continue;
    for (const hit of block.content) if (hit.url && !seen.has(hit.url)) seen.set(hit.url, hit.title ?? hit.url);
  }
  return [...seen].map(([url, title]) => ({ url, title }));
}

/** Short company facts every prompt may use; nothing beyond these may be invented. */
const BEER_FACTS = `BEER Küchenmanufaktur: Schreinerei und Küchenmanufaktur mit eigener Fertigung und Ausstellung in Wolfersdorf bei Freising (Bayern). Plant und baut Küchen und Möbel nach Maß für Kundinnen und Kunden im Raum München, Freising, Landshut und Umgebung. Arbeitet mit Geräten und Materialien unter anderem von Bora, Miele, Gaggenau, Siemens, Quooker und Fenix.`;

/* eslint-disable @typescript-eslint/no-unused-vars -- shared helpers, pasted in front of the newsletter Code nodes */
/**
 * Newsletter helpers, pasted by pack-workflows.mjs in front of the Code nodes of "BEER Newsletter":
 * sender, links, the e-mail layout, placeholders, and the public pages (confirm, unsubscribe)
 * that subscribers see. Nothing here talks to an API.
 */

// Sender and reply address. The sender must be an address the SMTP account may send from
// (with SPF/DKIM for beer.de), otherwise the mails land in spam.
const NL_FROM = "BEER Küchenmanufaktur <newsletter@beer.de>";
const NL_REPLY_TO = "info@beer.de";
// Public links in mails. Subscribers cannot open staging (password), so mails point to beer.de;
// /impressum and /datenschutz exist there once the new site is live.
const NL_SITE = "https://www.beer.de";
const NL_HOOK = "https://n8n.beer.de/webhook/beer-newsletter";
// A confirmation link older than this no longer confirms (the person signs up again).
const NL_CONFIRM_DAYS = 30;

const nlConfirmUrl = (token) => `${NL_HOOK}/bestaetigen?t=${encodeURIComponent(token)}`;
const nlUnsubscribeUrl = (token) => `${NL_HOOK}/abmelden?t=${encodeURIComponent(token)}`;
const nlLang = (value) => (value === "en" ? "en" : "de");
const nlEmail = (value) => {
  const email = String(value ?? "").trim().toLowerCase().slice(0, 160);
  return /^[^\s@<>"]+@[^\s@<>"]+\.[a-z]{2,}$/i.test(email) ? email : "";
};

const NL_WORDS = {
  de: {
    greeting: (name) => (name ? `Guten Tag ${name},` : "Guten Tag,"),
    footerWhy: "Sie erhalten diese E-Mail, weil Sie den Newsletter der BEER Küchenmanufaktur abonniert haben.",
    unsubscribe: "Newsletter abbestellen",
    imprint: "Impressum",
    privacy: "Datenschutz",
  },
  en: {
    greeting: (name) => (name ? `Hello ${name},` : "Hello,"),
    footerWhy: "You are receiving this e-mail because you subscribed to the BEER Küchenmanufaktur newsletter.",
    unsubscribe: "Unsubscribe",
    imprint: "Legal notice",
    privacy: "Privacy",
  },
};

/** The legal footer every newsletter ends with: why, unsubscribe link, address, imprint. */
function nlFooter(lang) {
  const w = NL_WORDS[nlLang(lang)];
  return `<tr><td style="padding:28px 32px 36px;border-top:1px solid #e3ded6;font:13px/1.6 Arial,Helvetica,sans-serif;color:#6b6760">
${esc(w.footerWhy)}<br><a href="{{abmelden_url}}" style="color:#1d1d1b">${esc(w.unsubscribe)}</a><br><br>
BEER GmbH · Badendorf 6 · 85395 Wolfersdorf · +49 8168 909910 · info@beer.de<br>
<a href="${NL_SITE}/impressum" style="color:#6b6760">${esc(w.imprint)}</a> · <a href="${NL_SITE}/datenschutz" style="color:#6b6760">${esc(w.privacy)}</a>
</td></tr>`;
}

/**
 * The BEER mail layout: wordmark, optional preview text (shown by mail apps next to the subject),
 * the content, the legal footer. Table layout and inline styles, so Outlook and Gmail show it alike.
 */
function nlLayout({ lang, preheader = "", content }) {
  return `<!doctype html><html lang="${nlLang(lang)}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BEER Küchenmanufaktur</title></head>
<body style="margin:0;padding:0;background:#f4f1ea">
<div style="display:none;max-height:0;overflow:hidden;opacity:0">${esc(preheader)}</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f1ea"><tr><td align="center" style="padding:24px 12px">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#ffffff">
<tr><td style="padding:28px 32px 8px;font:600 22px/1 Georgia,'Times New Roman',serif;letter-spacing:0.18em;color:#1d1d1b">BEER</td></tr>
<tr><td style="padding:0 32px;font:12px/1.4 Arial,Helvetica,sans-serif;letter-spacing:0.08em;color:#8a7a5c;text-transform:uppercase">Küchenmanufaktur · Wolfersdorf</td></tr>
${content}
${nlFooter(lang)}
</table></td></tr></table></body></html>`;
}

/** A large dark button that works in all mail apps. */
function nlButton(label, href) {
  return `<table role="presentation" cellpadding="0" cellspacing="0" style="margin:8px 0 8px"><tr><td style="background:#1d1d1b">
<a href="${esc(href)}" style="display:inline-block;padding:14px 26px;font:15px/1 Arial,Helvetica,sans-serif;color:#ffffff;text-decoration:none">${esc(label)}</a></td></tr></table>`;
}

/**
 * Plain text from the send page → mail content. Blank lines separate paragraphs; a line starting
 * with "## " is a subheading; "[Text](https://…)" is a link; a line "-> Text | https://…" is a button;
 * a line "Bild: https://…" is a photo across the full width.
 */
function nlFromText({ headline, text }) {
  const inline = (line) =>
    esc(line).replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, (_, label, href) => `<a href="${href}" style="color:#1d1d1b">${label}</a>`);
  const blocks = String(text ?? "")
    .replace(/\r\n/g, "\n")
    .split(/\n{2,}/)
    .map((block) => block.trim())
    .filter(Boolean)
    .map((block) => {
      const button = block.match(/^->\s*(.+?)\s*\|\s*(https?:\/\/\S+)$/);
      if (button) return `<tr><td style="padding:8px 32px">${nlButton(button[1], button[2])}</td></tr>`;
      const photo = block.match(/^Bild:\s*(https:\/\/\S+)$/i);
      if (photo) return `<tr><td style="padding:12px 0"><img src="${esc(photo[1])}" width="600" alt="" style="display:block;width:100%;max-width:600px;height:auto;border:0"></td></tr>`;
      if (block.startsWith("## ")) return `<tr><td style="padding:18px 32px 0;font:500 22px/1.25 Georgia,'Times New Roman',serif;color:#1d1d1b">${inline(block.slice(3))}</td></tr>`;
      return `<tr><td style="padding:12px 32px 0;font:16px/1.65 Arial,Helvetica,sans-serif;color:#33312d">${block.split("\n").map(inline).join("<br>")}</td></tr>`;
    });
  const title = headline
    ? `<tr><td style="padding:28px 32px 4px;font:500 30px/1.15 Georgia,'Times New Roman',serif;color:#1d1d1b">${esc(headline)}</td></tr>`
    : `<tr><td style="padding:12px 0 0"></td></tr>`;
  return `${title}${blocks.join("\n")}<tr><td style="padding:0 0 28px"></td></tr>`;
}

/** Fills the placeholders a newsletter may use: {{anrede}}, {{vorname}}, {{email}}, {{abmelden_url}}. */
function nlPersonalize(html, { lang, vorname = "", email = "", token = "" }) {
  const values = {
    anrede: NL_WORDS[nlLang(lang)].greeting(vorname),
    vorname,
    email,
    abmelden_url: token ? nlUnsubscribeUrl(token) : `${NL_HOOK}/abmelden`,
  };
  return String(html).replace(/\{\{\s*(anrede|vorname|email|abmelden_url)\s*\}\}/g, (_, key) =>
    key === "abmelden_url" ? values[key] : esc(values[key]),
  );
}

/** A readable text version for mail apps without HTML (and for spam filters). */
function nlText(html) {
  return String(html)
    .replace(/<div style="display:none[\s\S]*?<\/div>/i, "")
    .replace(/<a [^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi, (_, href, label) => `${label.replace(/<[^>]+>/g, "")} (${href})`)
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/(p|tr|h[1-6]|li|div)>/gi, "\n\n")
    .replace(/<[^>]+>/g, "")
    .replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"')
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

/** A short fingerprint of a newsletter, so the same mail is not sent to everyone twice by accident. */
function nlFingerprint(value) {
  let hash = 0x811c9dc5;
  for (const char of String(value)) {
    hash ^= char.codePointAt(0);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash.toString(16).padStart(8, "0");
}

/** A simple BEER page for subscribers (confirm, unsubscribe): no navigation, one message. */
function nlPage(lang, title, body) {
  return `<!doctype html><html lang="${nlLang(lang)}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex">
<title>${esc(title)} · BEER Küchenmanufaktur</title><style>
body{margin:0;background:#f4f1ea;color:#1d1d1b;font:16px/1.6 system-ui,-apple-system,"Segoe UI",sans-serif}
main{max-width:560px;margin:8vh auto;padding:40px 32px;background:#fff}
.mark{font:600 22px/1 Georgia,serif;letter-spacing:.18em}.sub{font-size:12px;letter-spacing:.08em;color:#8a7a5c;text-transform:uppercase;margin-top:6px}
h1{font:500 32px/1.15 Georgia,serif;margin:32px 0 12px}p{margin:0 0 14px;color:#33312d}a{color:#1d1d1b}
button{font:inherit;padding:13px 24px;background:#1d1d1b;color:#fff;border:0;cursor:pointer}small{color:#6b6760}</style></head>
<body><main><div class="mark">BEER</div><div class="sub">Küchenmanufaktur · Wolfersdorf</div><h1>${esc(title)}</h1>${body}
<p><small><a href="${NL_SITE}">beer.de</a> · <a href="${NL_SITE}/datenschutz">${nlLang(lang) === "en" ? "Privacy" : "Datenschutz"}</a></small></p></main></body></html>`;
}

/**
 * n8n Code node "Seite" (workflow "BEER Newsletter"): the newsletter page for the team.
 * Who is subscribed, what was sent, and the form for a new newsletter: text in the BEER layout
 * or own HTML (file or pasted). Preview opens the mail in the browser; a test goes to the
 * addresses given; "Alle" needs the word SENDEN, so nothing goes out by a slip of the mouse.
 */
const rows = $("Abonnenten lesen").all().map((item) => item.json).filter((row) => row && row.id && row.email);
const sends = $("Versand lesen").all().map((item) => item.json).filter((row) => row && row.id);
const query = $("Seite aufrufen").first().json.query || {};

const count = (status, lang) => rows.filter((row) => row.status === status && (!lang || row.sprache === lang)).length;
const STATUS = { bestaetigt: "bestätigt", ausstehend: "wartet auf Bestätigung", abgemeldet: "abgemeldet" };
const notice =
  query.gestartet === "test" ? "Testmail ist unterwegs. Prüfen Sie das Postfach (auch den Spam-Ordner)."
  : query.gestartet === "alle" ? "Versand läuft. Er erscheint unten im Verlauf, sobald alle Mails raus sind."
  : query.geloescht ? "Eintrag gelöscht."
  : "";

const sorted = [...rows].sort((a, b) => String(b.angemeldet_am ?? "").localeCompare(String(a.angemeldet_am ?? "")));
const subscribers = sorted.length
  ? `<table><tr><th>E-Mail</th><th>Name</th><th>Sprache</th><th>Status</th><th>Angemeldet</th><th>Bestätigt</th><th>Quelle</th><th></th></tr>
${sorted.slice(0, 300).map((row) => `<tr><td>${esc(row.email)}</td><td>${esc(row.vorname)}</td><td>${esc(row.sprache)}</td>
<td class="${row.status === "bestaetigt" ? "ok" : row.status === "abgemeldet" ? "small" : "hinweis"}">${esc(STATUS[row.status] ?? row.status)}${row.abgemeldet_am ? `<div class="small">${esc(when(row.abgemeldet_am))}</div>` : ""}</td>
<td class="small">${esc(when(row.angemeldet_am))}</td><td class="small">${esc(when(row.bestaetigt_am))}</td><td class="small">${esc(row.quelle)}</td>
<td><form method="post" action="/webhook/beer-newsletter/loeschen" onsubmit="return confirm('${esc(row.email)} endgültig löschen? Das lässt sich nicht rückgängig machen.')"><input type="hidden" name="id" value="${esc(row.id)}"><button>Löschen</button></form></td></tr>`).join("")}</table>
${sorted.length > 300 ? `<p class="small">Die ersten 300 von ${sorted.length}. Alle stehen in n8n unter „Data tables“ → newsletter_abonnenten.</p>` : ""}`
  : `<p class="small">Noch niemand. Anmeldungen kommen vom Formular auf der Website (Fußzeile und Küchenplaner).</p>`;

const history = sends.length
  ? `<table><tr><th>Gesendet</th><th>Betreff</th><th>Sprache</th><th>Art</th><th>Empfänger</th><th>Fehler</th></tr>
${[...sends].sort((a, b) => String(b.gestartet_am ?? "").localeCompare(String(a.gestartet_am ?? ""))).slice(0, 50).map((row) => `<tr><td class="small">${esc(when(row.fertig_am || row.gestartet_am))}</td><td>${esc(row.betreff)}</td><td>${esc(row.sprache)}</td><td>${row.test ? "Test" : "<b>Alle</b>"}</td><td>${esc(row.gesendet)} von ${esc(row.empfaenger)}</td><td class="${row.fehler ? "fehler" : "small"}">${esc(row.fehler || "–")}</td></tr>`).join("")}</table>`
  : `<p class="small">Noch nichts gesendet.</p>`;

const html = page(
  "Newsletter",
  "Newsletter",
