const NL_CONFIRM_DAYS = 30;

const nlConfirmUrl = (token) => `${NL_HOOK}/bestaetigen?t=${encodeURIComponent(token)}`;
const nlUnsubscribeUrl = (token) => `${NL_HOOK}/abmelden?t=${encodeURIComponent(token)}`;
